/** Read only the studio's bounded, store-only flat character ZIP format. */
import {crc32} from './zip-export.mjs';
import {validateActorContract,inspectActorGLB,actorHash} from '../src/fps/character-runtime-contract.mjs?v=6.1.0';
const allowed=new Set(['CHARACTER.glb','CHARACTER.json','PROJECT.json','BASE_RIG.glb','COMPATIBILITY.json','README.txt']);
export async function readRuntimePackage(input){
 const b=input instanceof Uint8Array?input:new Uint8Array(input),d=new DataView(b.buffer,b.byteOffset,b.length),text=new TextDecoder('utf-8',{fatal:true}),files=new Map(),records=[];
 if(b.length<22||b.length>96*1024*1024)throw Error('Karaktärspaketet är för stort eller avbrutet.');let at=0;
 while(at+4<=b.length&&d.getUint32(at,true)===0x04034b50){
  if(at+30>b.length)throw Error('Avbruten ZIP.');const flag=d.getUint16(at+6,true),method=d.getUint16(at+8,true),crc=d.getUint32(at+14,true),size=d.getUint32(at+18,true),unpacked=d.getUint32(at+22,true),n=d.getUint16(at+26,true),extra=d.getUint16(at+28,true),start=at+30+n;
  if(flag!==0x800||method!==0||size!==unpacked||extra||n>80||!n||start+size>b.length)throw Error('Exportera paketet direkt från Character Design Studio.');
  const name=text.decode(b.subarray(at+30,start));if(!allowed.has(name)||files.has(name))throw Error('Okänd eller duplicerad paketfil.');
  const data=b.slice(start,start+size);if(crc32(data)!==crc)throw Error('Paketets kontrollsumma stämmer inte.');files.set(name,data);records.push({name,at,crc,size});at=start+size;
 }
 const directory=at;
 for(const row of records){
  if(at+46>b.length||d.getUint32(at,true)!==0x02014b50)throw Error('ZIP-katalog saknas.');const n=d.getUint16(at+28,true);
  if(n>80||at+46+n>b.length||d.getUint16(at+30,true)||d.getUint16(at+32,true)||text.decode(b.subarray(at+46,at+46+n))!==row.name||d.getUint32(at+16,true)!==row.crc||d.getUint32(at+20,true)!==row.size||d.getUint32(at+24,true)!==row.size||d.getUint32(at+42,true)!==row.at)throw Error('Ändrad ZIP-katalog.');at+=46+n;
 }
 if(at+22!==b.length||d.getUint32(at,true)!==0x06054b50||d.getUint16(at+4,true)||d.getUint16(at+6,true)||d.getUint16(at+8,true)!==records.length||d.getUint16(at+10,true)!==records.length||d.getUint32(at+12,true)!==at-directory||d.getUint32(at+16,true)!==directory||d.getUint16(at+20,true))throw Error('Ogiltigt ZIP-slut.');
 for(const name of ['CHARACTER.glb','CHARACTER.json','PROJECT.json','BASE_RIG.glb'])if(!files.has(name))throw Error('Paketfil saknas: '+name);
 if(files.get('CHARACTER.json').length>65536)throw Error('För stort karaktärskontrakt.');
 const contract=validateActorContract(JSON.parse(text.decode(files.get('CHARACTER.json')))),bytes=files.get('CHARACTER.glb');
 if(bytes.length!==contract.bytes||await actorHash(bytes)!==contract.sha256)throw Error('Karaktärens identitet stämmer inte.');inspectActorGLB(bytes);inspectActorGLB(files.get('BASE_RIG.glb'));
 return {contract,bytes,files};
}

/** Low-profile, continuous footwear. No stacked boxes, shafts or floating laces.
 * Coordinates are the original operator bind space; skeleton and motions unchanged.
 */
import * as T from '../../vendor/three/three.module.js';
const outline=[[-.043,-.105],[-.057,-.078],[-.059,-.015],[-.063,.045],[-.058,.105],[-.036,.135],[0,.143],[.036,.135],[.058,.105],[.063,.045],[.059,-.015],[.057,-.078],[.043,-.105],[0,-.112]];
function loft(rings){
 const vertices=[],uv=[],indices=[],n=outline.length;
 for(let r=0;r<rings.length;r++)for(let i=0;i<n;i++){
  const [sx,sz,y,zshift]=rings[r],[x,z]=outline[i];vertices.push(x*sx,y,z*sz+zshift);uv.push(i/n,r/(rings.length-1));
 }
 for(let r=0;r<rings.length-1;r++)for(let i=0;i<n;i++){
  const a=r*n+i,b=r*n+(i+1)%n,c=a+n,d=b+n;indices.push(a,c,b,b,c,d);
 }
 for(const [r,flip]of [[0,true],[rings.length-1,false]]){
  const start=vertices.length/3,ys=rings[r][2];vertices.push(0,ys,rings[r][3]);uv.push(.5,.5);
  for(let i=0;i<n;i++){const a=r*n+i,b=r*n+(i+1)%n;indices.push(...(flip?[start,b,a]:[start,a,b]));}
 }
 for(let i=0;i<indices.length;i+=3)[indices[i+1],indices[i+2]]=[indices[i+2],indices[i+1]];
 const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(vertices,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(indices);g.computeVertexNormals();g.computeBoundingBox();return g;
}
export function makeFootwear(){
 // Rounded toe-box narrows into a modest ankle collar under the trouser cuff.
 return {
 sole:loft([[.96,.99,.008,.026],[1,1,.017,.026],[1,1,.032,.026],[.96,.98,.037,.026]]),
 upper:loft([[.96,.98,.033,.026],[.94,.96,.057,.026],[.89,.85,.079,.018],[.72,.52,.105,-.009],[.69,.40,.143,-.023],[.69,.40,.184,-.023]])
 };
}
export function isLegacyFootwear(mesh){return mesh.userData?.legacyFootwear===true||mesh.material?.name==='boots-leather';}

/** Cosmetic roster; authored GLBs replace visuals, never actor/gameplay data. */
import {GLTFLoader} from '../../vendor/three/addons/loaders/GLTFLoader.js';
import {assignmentKeys} from './character-roles.mjs?v=6.1.0';
import {inspectActorGLB,validateActorContract,validateActorAsset,actorHash} from './character-runtime-contract.mjs?v=6.1.0';
import {createDwarfAsset} from './dwarf-rig.mjs?v=6.1.0';
let entries=new Map(),pending=null;
function disposeEntry(entry){
 entry.viewAppearance?.dispose();if(!entry.ownsAsset)return;
 const geometries=new Set(),materials=new Set(),textures=new Set(),skeletons=new Set();
 entry.asset.scene.traverse(n=>{if(n.geometry)geometries.add(n.geometry);if(n.skeleton)skeletons.add(n.skeleton);for(const m of [n.material].flat().filter(Boolean))materials.add(m);});
 for(const m of materials){for(const t of Object.values(m))if(t?.isTexture)textures.add(t);m.dispose();}
 for(const g of geometries)g.dispose();for(const t of textures)t.dispose();for(const s of skeletons)s.dispose();
}
export function getCharacterOverride(role,id,variant=0){for(const target of assignmentKeys(role,id,variant)){const entry=entries.get(target);if(entry?.contract.role===role)return entry;}return null;}
/** Host/test integration: caller owns this already parsed asset and its lifetime. */
export function installCharacterOverride(asset,contract,source){const report=validateActorAsset(asset,contract,source);const entry={asset,contract,report,signature:contract.sha256,ownsAsset:false};entries.set(contract.target,entry);return entry;}
export async function loadCharacterOverrides(sources){
 if(pending)return pending;
 pending=(async()=>{
  const response=await fetch(new URL('../../assets/fps/character-overrides.json',import.meta.url),{cache:'no-store'});if(!response.ok)throw Error('Karaktärsregistret kunde inte läsas.');
  const manifest=await response.json();if(manifest.schema!==1||!Array.isArray(manifest.characters)||manifest.characters.length>48)throw Error('Ogiltigt karaktärsregister.');
  const staged=new Map(),loader=new GLTFLoader(),sourceHashes=new Map();
  try{for(const row of manifest.characters){
   const c=validateActorContract(row.contract);if(staged.has(c.target)||row.file!==`assets/fps/custom-characters/${c.sha256}.glb`)throw Error('Ogiltig eller duplicerad karaktärssökväg.');
   if(c.role!=='dwarf'){
    if(!sourceHashes.has(c.gender)){const original=await fetch(new URL('../../assets/fps/models/'+c.source.file,import.meta.url));if(!original.ok)throw Error('Originalriggen saknas.');sourceHashes.set(c.gender,await actorHash(await original.arrayBuffer()));}
    if(sourceHashes.get(c.gender)!==c.source.sha256)throw Error('Exporten bygger på en annan originalrigg. Exportera på nytt från studion.');
   }
   const r=await fetch(new URL('../../'+row.file,import.meta.url));if(!r.ok)throw Error('Karaktärsfil saknas: '+c.target);const bytes=await r.arrayBuffer();
   if(bytes.byteLength!==c.bytes||await actorHash(bytes)!==c.sha256)throw Error('Karaktärens kontrollsumma stämmer inte.');inspectActorGLB(bytes);
   const source=c.role==='dwarf'?createDwarfAsset():sources[c.gender];
   const asset=await loader.parseAsync(bytes,'');let report;
   try{report=validateActorAsset(asset,c,source);}catch(e){disposeEntry({asset,ownsAsset:true});throw e;}finally{if(c.role==='dwarf')disposeEntry({asset:source,ownsAsset:true});}
   staged.set(c.target,{asset,contract:c,report,signature:c.sha256,ownsAsset:true});
  }}catch(e){for(const entry of staged.values())disposeEntry(entry);throw e;}
  for(const entry of entries.values())disposeEntry(entry);entries=staged;
 })().catch(error=>{pending=null;throw error;});return pending;
}
export function clearCharacterOverrides(){for(const entry of entries.values())disposeEntry(entry);entries.clear();pending=null;}
